import numpy as np
from scipy import optimize, stats
from calibrate import DATA, SEGS, KINDS


def fit(ys, family, nu=None):
    med = np.array([np.median(y) for y in ys])
    x0 = np.r_[med, np.log(50. if family != 'normal' else 70.)]
    def nll(x):
        scale=np.exp(x[6])
        out=0.
        for y,m in zip(ys,x[:6]):
            z=(y-m)/scale
            if family=='t': out-=np.sum(stats.t.logpdf(z,nu)-np.log(scale))
            elif family=='normal': out-=np.sum(stats.norm.logpdf(z)-np.log(scale))
            elif family=='logistic': out-=np.sum(stats.logistic.logpdf(z)-np.log(scale))
            elif family=='laplace': out-=np.sum(stats.laplace.logpdf(z)-np.log(scale))
        return out
    r=optimize.minimize(nll,x0,method='Nelder-Mead',options={'maxiter':12000,'xatol':1e-8,'fatol':1e-7})
    return r.x


def loglik(ys,x,family,nu=None):
    scale=np.exp(x[6]); out=0.
    for y,m in zip(ys,x[:6]):
        z=(y-m)/scale
        if family=='t': out+=np.sum(stats.t.logpdf(z,nu)-np.log(scale))
        elif family=='normal': out+=np.sum(stats.norm.logpdf(z)-np.log(scale))
        elif family=='logistic': out+=np.sum(stats.logistic.logpdf(z)-np.log(scale))
        elif family=='laplace': out+=np.sum(stats.laplace.logpdf(z)-np.log(scale))
    return out

for kind in KINDS:
    print('\n'+kind)
    candidates=[('normal',None),('logistic',None),('laplace',None),('t',1.),('t',2.),('t',3.),('t',4.),('t',5.),('t',6.),('t',8.)]
    cv={c:0. for c in candidates}
    for fold in range(5):
        train=[]; test=[]
        for s in SEGS:
            y=DATA[(s,kind)]; idx=np.arange(len(y))%5==fold
            train.append(y[~idx]); test.append(y[idx])
        for c in candidates:
            x=fit(train,*c)
            cv[c]+=loglik(test,x,*c)
    for c,v in sorted(cv.items(),key=lambda kv:-kv[1]): print(c,'CV loglik',round(v,3))

    # Fit representative model and compare pooled standardized residual quantiles/tail frequencies.
    c = ('t',4.) if kind=='income' else ('t',1.)
    x=fit([DATA[(s,kind)] for s in SEGS],*c)
    z=np.concatenate([(DATA[(s,kind)]-m)/np.exp(x[6]) for s,m in zip(SEGS,x[:6])])
    print('chosen',c,'loc',np.round(x[:6],4),'scale',np.exp(x[6]))
    print('|z| quantiles',[(q,round(np.quantile(np.abs(z),q),3),round((stats.t.ppf((1+q)/2,c[1]) if c[0]=='t' else 0),3)) for q in [.25,.5,.75,.9,.95,.975,.99]])
    for threshold in [1,2,3,4,5,6,8,10]:
        empirical=np.mean(np.abs(z)>threshold)
        expected=2*stats.t.sf(threshold,c[1])
        print('tail',threshold,'emp',round(empirical,4),'expected',round(expected,4))

