class IncomePolicy:
    """Exact finite-horizon adaptive policy when subsequent checks are income-only."""
    def __init__(self,base,remaining):
        self.base=np.asarray(base,dtype=float)
        self.remaining=int(remaining)
        self.loglik=np.log(LIK['income'])
        self.decision_by_state={}
        self._value(self._zero())

    def _zero(self):
        return (0,)*6

    def _posterior(self,counts):
        p=self.base.copy()
        for band,n in enumerate(counts):
            if n: p*=LIK['income'][band]**n
        return p/p.sum()

    @lru_cache(maxsize=None)
    def _value(self,counts):
        used=sum(counts)
        p=self._posterior(counts)
        stop=max(0.,float(p@VALUES))
        if used>=self.remaining:
            self.decision_by_state[counts]=('stop',stop)
            return stop
        q=p@LIK['income']
        check=-20.
        for band in range(6):
            child=list(counts); child[band]+=1
            check+=q[band]*self._value(tuple(child))
        if check>stop+1e-9:
            self.decision_by_state[counts]=('income',check)
            return check
        self.decision_by_state[counts]=('stop',stop)
        return stop

    def root_value(self):
        return self._value(self._zero())

    def root_action(self):
        return self.decision_by_state[self._zero()]

    def max_planned_checks(self):
        return max((sum(c) for c,(a,v) in self.decision_by_state.items() if a=='income'),default=0)+1


def adaptive_advice(prior,history=(),alternatives=True):
    p=posterior(prior,history)
    remaining=8-len(history)
    policy=IncomePolicy(p,remaining)
    stop=max(0.,float(p@VALUES))
    print('adaptive posterior',dict(zip(SEGS,np.round(p,8))))
    print('terminal',decision(p),'remaining',remaining)
    if remaining==0:
        print('ADAPTIVE ADVICE',decision(p)[0])
        return policy
    qvalues={'income':policy._value((1,0,0,0,0,0))*0}  # replaced explicitly below
    q=p@LIK['income']
    qvalues['income']=-20.+sum(q[b]*policy._value(tuple(1 if j==b else 0 for j in range(6))) for b in range(6))
    if alternatives:
        for kind in ['bureau','bank']:
            qk=p@LIK[kind]
            value=-20.
            children=[]
            for b in range(6):
                child=p*LIK[kind][b]; child/=child.sum()
                continuation=IncomePolicy(child,remaining-1).root_value()
                children.append((b,float(qk[b]),child.copy(),continuation))
                value+=qk[b]*continuation
            qvalues[kind]=value
            print(kind,'child continuation',children)
    print('adaptive stop value',stop,'check Q with income continuation',qvalues,'income policy value',policy.root_value(),'max additional checks',policy.max_planned_checks(),'states',len(policy.decision_by_state))
    best_kind=max(qvalues,key=qvalues.get)
    if qvalues[best_kind]>stop+1e-7:
        print('ADAPTIVE ADVICE run',best_kind)
    else:
        print('ADAPTIVE ADVICE',decision(p)[0])
    return policy


if __name__=='__main__':
    print('values',VALUES)

